-- Core schema: households, profiles, membership and every synced table.
--
-- Sync conventions (all synced tables):
--   id                uuid PK generated by the client (server code may default it)
--   household_id      owning household; immutable after insert
--   created_at        set on insert
--   updated_at        set on every write by private.sync_row()
--   updated_by        auth.uid() of the last writer
--   deleted_at        tombstone; rows are never hard-deleted by clients
--   client_updated_at client_ts of the last mutation applied through apply_mutations (row LWW)
--   server_seq        value from the global sequence public.sync_seq, set on every write.
--                     Writers are serialised with a transaction-level advisory lock so that
--                     server_seq order equals commit order and the pull cursor never skips rows.

-- ---------------------------------------------------------------------------
-- Enums
-- ---------------------------------------------------------------------------
create type public.product_category as enum ('basics', 'food', 'cleaning', 'kitchen', 'bathroom', 'toiletries');
create type public.meal_slot as enum ('breakfast', 'lunch', 'snack', 'dinner');
create type public.household_role as enum ('owner', 'member');
create type public.draft_status as enum ('pending', 'accepted', 'discarded');
create type public.draft_source as enum ('mcp', 'app', 'ai');
create type public.shopping_kind as enum ('product', 'recipe', 'text');
create type public.shopping_source as enum ('manual', 'plan', 'siri', 'widget', 'mcp');
create type public.device_platform as enum ('ios', 'macos');
create type public.apns_environment as enum ('sandbox', 'production');

-- ---------------------------------------------------------------------------
-- Generic trigger helpers
-- ---------------------------------------------------------------------------
create or replace function private.touch_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

create sequence public.sync_seq as bigint;
revoke all on sequence public.sync_seq from public, anon, authenticated;

-- Single lock key shared by every writer of synced tables (see header comment).
create or replace function private.sync_lock()
returns void
language sql
set search_path = ''
as $$
  select pg_advisory_xact_lock(hashtextextended('koda.sync_seq', 0));
$$;

create or replace function private.sync_row()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.sync_lock();
  if tg_op = 'INSERT' then
    new.created_at := now();
  else
    new.id := old.id;
    new.created_at := old.created_at;
    new.household_id := old.household_id;
  end if;
  new.updated_at := now();
  new.updated_by := coalesce(auth.uid(), new.updated_by);
  new.server_seq := nextval('public.sync_seq');
  return new;
end;
$$;

-- AFTER UPDATE trigger: when a parent gets a tombstone, tombstone its live children.
-- Arguments: child table, child column.
create or replace function private.cascade_tombstone()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if old.deleted_at is null and new.deleted_at is not null then
    execute format(
      'update public.%I set deleted_at = $1 where %I = $2 and deleted_at is null',
      tg_argv[0], tg_argv[1]
    ) using new.deleted_at, new.id;
  end if;
  return null;
end;
$$;

-- ---------------------------------------------------------------------------
-- Households and membership (not synced; read through /me)
-- ---------------------------------------------------------------------------
create table public.households (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(btrim(name)) > 0),
  timezone text not null default 'Europe/Madrid',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  display_name text not null check (length(btrim(display_name)) > 0),
  avatar_emoji text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.household_members (
  household_id uuid not null references public.households (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  role public.household_role not null default 'member',
  created_at timestamptz not null default now(),
  primary key (household_id, user_id)
);
create index household_members_user_id_idx on public.household_members (user_id);

create trigger households_touch before update on public.households
  for each row execute function private.touch_updated_at();
create trigger profiles_touch before update on public.profiles
  for each row execute function private.touch_updated_at();

-- Used by every RLS policy. SECURITY DEFINER avoids recursive RLS on household_members.
create or replace function public.household_ids_for_user()
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select hm.household_id from public.household_members hm where hm.user_id = (select auth.uid());
$$;

-- ---------------------------------------------------------------------------
-- Catalog: stores and products
-- ---------------------------------------------------------------------------
create table public.stores (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  name text not null check (length(btrim(name)) > 0),
  color text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid() references auth.users (id) on delete set null,
  deleted_at timestamptz,
  client_updated_at timestamptz,
  server_seq bigint not null default 0,
  unique (id, household_id)
);

create table public.products (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  name text not null check (length(btrim(name)) > 0),
  category public.product_category not null default 'food',
  default_unit text,
  price_per_kg numeric(10, 2) check (price_per_kg >= 0),
  price_total numeric(10, 2) check (price_total >= 0),
  servings numeric check (servings >= 0),
  servings_per_week numeric check (servings_per_week >= 0),
  notes text,
  emoji text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid() references auth.users (id) on delete set null,
  deleted_at timestamptz,
  client_updated_at timestamptz,
  server_seq bigint not null default 0,
  unique (id, household_id)
);

create table public.product_stores (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  product_id uuid not null,
  store_id uuid not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid() references auth.users (id) on delete set null,
  deleted_at timestamptz,
  client_updated_at timestamptz,
  server_seq bigint not null default 0,
  foreign key (product_id, household_id) references public.products (id, household_id) on delete cascade,
  foreign key (store_id, household_id) references public.stores (id, household_id) on delete cascade
);
create unique index product_stores_live_unique on public.product_stores (product_id, store_id) where deleted_at is null;

-- ---------------------------------------------------------------------------
-- Recipes
-- ---------------------------------------------------------------------------
create table public.recipes (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  name text not null check (length(btrim(name)) > 0),
  meal_types text[] not null default '{}'
    check (meal_types <@ array['breakfast', 'lunch', 'snack', 'dinner']::text[]),
  nutrients text[] not null default '{}'
    check (nutrients <@ array['fats', 'fiber', 'vegetables', 'protein', 'carbs']::text[]),
  time_minutes integer check (time_minutes >= 0),
  servings numeric not null default 2 check (servings > 0),
  steps jsonb not null default '[]'::jsonb check (jsonb_typeof(steps) = 'array'),
  notes text,
  image_path text,
  emoji text,
  is_favorite boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid() references auth.users (id) on delete set null,
  deleted_at timestamptz,
  client_updated_at timestamptz,
  server_seq bigint not null default 0,
  unique (id, household_id)
);

create table public.recipe_ingredients (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  recipe_id uuid not null,
  product_id uuid not null,
  quantity numeric check (quantity > 0),
  unit text,
  position integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid() references auth.users (id) on delete set null,
  deleted_at timestamptz,
  client_updated_at timestamptz,
  server_seq bigint not null default 0,
  foreign key (recipe_id, household_id) references public.recipes (id, household_id) on delete cascade,
  foreign key (product_id, household_id) references public.products (id, household_id) on delete cascade
);

-- "Pollo al horno" includes "Patatas al airfryer". Cycles are rejected by a trigger.
create table public.recipe_components (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  parent_recipe_id uuid not null,
  child_recipe_id uuid not null,
  servings_factor numeric not null default 1 check (servings_factor > 0),
  position integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid() references auth.users (id) on delete set null,
  deleted_at timestamptz,
  client_updated_at timestamptz,
  server_seq bigint not null default 0,
  check (parent_recipe_id <> child_recipe_id),
  foreign key (parent_recipe_id, household_id) references public.recipes (id, household_id) on delete cascade,
  foreign key (child_recipe_id, household_id) references public.recipes (id, household_id) on delete cascade
);

-- ---------------------------------------------------------------------------
-- Planning and history
-- ---------------------------------------------------------------------------
create table public.meal_plan_drafts (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  from_date date not null,
  to_date date not null,
  status public.draft_status not null default 'pending',
  source public.draft_source not null default 'app',
  rationale text,
  created_by uuid default auth.uid() references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid() references auth.users (id) on delete set null,
  deleted_at timestamptz,
  client_updated_at timestamptz,
  server_seq bigint not null default 0,
  check (to_date >= from_date),
  unique (id, household_id)
);

-- Entries with draft_id are part of a draft and are not shown in the planning until accepted.
create table public.meal_plan_entries (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  date date not null,
  slot public.meal_slot not null,
  recipe_id uuid,
  free_text text,
  servings numeric check (servings > 0),
  note text,
  position integer not null default 0,
  draft_id uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid() references auth.users (id) on delete set null,
  deleted_at timestamptz,
  client_updated_at timestamptz,
  server_seq bigint not null default 0,
  check (recipe_id is not null or free_text is not null),
  unique (id, household_id),
  foreign key (recipe_id, household_id) references public.recipes (id, household_id) on delete cascade,
  foreign key (draft_id, household_id) references public.meal_plan_drafts (id, household_id) on delete cascade
);

-- History of "we ate X on day Y". Source for suggestions and the MCP.
create table public.consumptions (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  recipe_id uuid not null,
  eaten_on date not null,
  slot public.meal_slot,
  servings numeric check (servings > 0),
  meal_plan_entry_id uuid,
  logged_by uuid default auth.uid() references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid() references auth.users (id) on delete set null,
  deleted_at timestamptz,
  client_updated_at timestamptz,
  server_seq bigint not null default 0,
  foreign key (recipe_id, household_id) references public.recipes (id, household_id) on delete cascade,
  foreign key (meal_plan_entry_id, household_id) references public.meal_plan_entries (id, household_id)
    on delete set null (meal_plan_entry_id)
);

-- ---------------------------------------------------------------------------
-- Shopping list
-- ---------------------------------------------------------------------------
create table public.shopping_entries (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  kind public.shopping_kind not null,
  product_id uuid,
  recipe_id uuid,
  text text,
  quantity numeric check (quantity > 0),
  unit text,
  checked boolean not null default false,
  checked_at timestamptz,
  checked_by uuid references auth.users (id) on delete set null,
  name_updated_at timestamptz,
  source public.shopping_source not null default 'manual',
  meal_plan_entry_id uuid,
  position integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid() references auth.users (id) on delete set null,
  deleted_at timestamptz,
  client_updated_at timestamptz,
  server_seq bigint not null default 0,
  check (kind <> 'product' or product_id is not null),
  check (kind <> 'text' or text is not null),
  unique (id, household_id),
  foreign key (product_id, household_id) references public.products (id, household_id) on delete cascade,
  foreign key (recipe_id, household_id) references public.recipes (id, household_id) on delete set null (recipe_id),
  foreign key (meal_plan_entry_id, household_id) references public.meal_plan_entries (id, household_id)
    on delete set null (meal_plan_entry_id)
);

-- Only for kind = 'recipe': flattened snapshot of the recipe and its sub-recipes.
create table public.shopping_entry_items (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  entry_id uuid not null,
  product_id uuid not null,
  quantity numeric check (quantity > 0),
  unit text,
  checked boolean not null default false,
  checked_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid() references auth.users (id) on delete set null,
  deleted_at timestamptz,
  client_updated_at timestamptz,
  server_seq bigint not null default 0,
  foreign key (entry_id, household_id) references public.shopping_entries (id, household_id) on delete cascade,
  foreign key (product_id, household_id) references public.products (id, household_id) on delete cascade
);

-- ---------------------------------------------------------------------------
-- Sync triggers and indexes for every synced table
-- ---------------------------------------------------------------------------
do $$
declare
  t text;
begin
  foreach t in array array[
    'stores', 'products', 'product_stores', 'recipes', 'recipe_ingredients', 'recipe_components',
    'meal_plan_drafts', 'meal_plan_entries', 'consumptions', 'shopping_entries', 'shopping_entry_items'
  ] loop
    -- BEFORE triggers fire in name order: "t10_" runs first so the advisory lock is taken early.
    execute format(
      'create trigger t10_sync_row before insert or update on public.%I for each row execute function private.sync_row()', t);
    execute format('create index %I on public.%I (household_id)', t || '_household_id_idx', t);
    execute format('create index %I on public.%I (server_seq)', t || '_server_seq_idx', t);
    execute format('create index %I on public.%I (deleted_at) where deleted_at is not null', t || '_deleted_at_idx', t);
  end loop;
end;
$$;

-- Foreign-key and query indexes.
create index product_stores_product_id_idx on public.product_stores (product_id);
create index product_stores_store_id_idx on public.product_stores (store_id);
create index products_name_trgm_idx on public.products using gin (public.normalize_text(name) extensions.gin_trgm_ops);
create index recipe_ingredients_recipe_id_idx on public.recipe_ingredients (recipe_id);
create index recipe_ingredients_product_id_idx on public.recipe_ingredients (product_id);
create index recipe_components_parent_idx on public.recipe_components (parent_recipe_id);
create index recipe_components_child_idx on public.recipe_components (child_recipe_id);
create index meal_plan_entries_household_date_idx on public.meal_plan_entries (household_id, date);
create index meal_plan_entries_recipe_id_idx on public.meal_plan_entries (recipe_id);
create index meal_plan_entries_draft_id_idx on public.meal_plan_entries (draft_id);
create index consumptions_recipe_eaten_idx on public.consumptions (recipe_id, eaten_on);
create index consumptions_meal_plan_entry_id_idx on public.consumptions (meal_plan_entry_id);
create index shopping_entries_product_id_idx on public.shopping_entries (product_id);
create index shopping_entries_recipe_id_idx on public.shopping_entries (recipe_id);
create index shopping_entries_meal_plan_entry_id_idx on public.shopping_entries (meal_plan_entry_id);
create index shopping_entry_items_entry_id_idx on public.shopping_entry_items (entry_id);
create index shopping_entry_items_product_id_idx on public.shopping_entry_items (product_id);

-- Tombstone cascades (parent -> live children).
create trigger t30_tombstone_product_stores after update of deleted_at on public.stores
  for each row execute function private.cascade_tombstone('product_stores', 'store_id');
create trigger t30_tombstone_product_stores after update of deleted_at on public.products
  for each row execute function private.cascade_tombstone('product_stores', 'product_id');
create trigger t31_tombstone_recipe_ingredients after update of deleted_at on public.products
  for each row execute function private.cascade_tombstone('recipe_ingredients', 'product_id');
create trigger t32_tombstone_shopping_entries after update of deleted_at on public.products
  for each row execute function private.cascade_tombstone('shopping_entries', 'product_id');
create trigger t33_tombstone_shopping_entry_items after update of deleted_at on public.products
  for each row execute function private.cascade_tombstone('shopping_entry_items', 'product_id');
create trigger t30_tombstone_recipe_ingredients after update of deleted_at on public.recipes
  for each row execute function private.cascade_tombstone('recipe_ingredients', 'recipe_id');
create trigger t31_tombstone_components_parent after update of deleted_at on public.recipes
  for each row execute function private.cascade_tombstone('recipe_components', 'parent_recipe_id');
create trigger t32_tombstone_components_child after update of deleted_at on public.recipes
  for each row execute function private.cascade_tombstone('recipe_components', 'child_recipe_id');
create trigger t33_tombstone_meal_plan_entries after update of deleted_at on public.recipes
  for each row execute function private.cascade_tombstone('meal_plan_entries', 'recipe_id');
create trigger t34_tombstone_consumptions after update of deleted_at on public.recipes
  for each row execute function private.cascade_tombstone('consumptions', 'recipe_id');
create trigger t30_tombstone_draft_entries after update of deleted_at on public.meal_plan_drafts
  for each row execute function private.cascade_tombstone('meal_plan_entries', 'draft_id');
create trigger t30_tombstone_entry_items after update of deleted_at on public.shopping_entries
  for each row execute function private.cascade_tombstone('shopping_entry_items', 'entry_id');
